import { Menubar } from 'primereact/menubar';
import { Badge } from 'primereact/badge';

import style from './NavBar.module.css'

export default function NavBar ({setSelectedPage}) {
 const itemRenderer = (item) => (
        <a className="flex align-items-center p-menuitem-link">
            <span className={item.icon} />
            <span className="mx-2">{item.label}</span>
            {item.badge && <Badge className="ml-auto" value={item.badge} />}
            {item.shortcut && <span className="ml-auto border-1 surface-border border-round surface-100 text-xs p-1">{item.shortcut}</span>}
        </a>
    );
    const items = [
        {
            label: 'Home',
            icon: 'pi pi-home',
            command: () => setSelectedPage('home')
        },
        {
            label: 'Features',
            icon: 'pi pi-star'
        },
        {
            label: 'Projects',
            icon: 'pi pi-search',
            items: [
                {
                    label: 'Core',
                    icon: 'pi pi-bolt',
                    shortcut: '⌘+S',
                    template: itemRenderer
                },
                {
                    label: 'Blocks',
                    icon: 'pi pi-server',
                    shortcut: '⌘+B',
                    template: itemRenderer
                },
                {
                    label: 'UI Kit',
                    icon: 'pi pi-pencil',
                    shortcut: '⌘+U',
                    template: itemRenderer
                },
                {
                    separator: true
                },
                {
                    label: 'Templates',
                    icon: 'pi pi-palette',
                    items: [
                        {
                            label: 'Apollo',
                            icon: 'pi pi-palette',
                            badge: 2,
                            template: itemRenderer
                        },
                        {
                            label: 'Ultima',
                            icon: 'pi pi-palette',
                            badge: 3,
                            template: itemRenderer
                        }
                    ]
                }
            ]
        },
        {
            label: 'Free trial class',
            icon: 'pi pi-verified',
            badge: 3,
            command: () => setSelectedPage('trialform')
        },{
            label: 'Blog',
            icon: 'pi pi-search',
            items: [
                {
                    label: 'Belt Ranks',
                    icon: 'pi pi-bolt',
                    template: itemRenderer,
                    command: () => setSelectedPage('beltranks')
                },
                {
                    label: 'Blocks',
                    icon: 'pi pi-server',
                    shortcut: '⌘+B',
                    template: itemRenderer
                },
                {
                    label: 'UI Kit',
                    icon: 'pi pi-pencil',
                    shortcut: '⌘+U',
                    template: itemRenderer
                },
    ]}
    ];

    const start = <img alt="logo" src="https://satoribjjacademy.com/wp-content/uploads/2026/02/Camada-1.png" height="40" className="mr-2"></img>;



    return(
        <div>
             <Menubar className={style["Navbar-style"]}  model={items} start={start} />
        </div>
    )
}
